def make(cid):
 # Compact rendering must be present before freeze/manifests.
 from build import RUN
 p=RUN/'inputs'/cid;p.mkdir(parents=True,exist_ok=True)
 (p/'critique-compact.md').write_text(COMPACT[cid])
